arguments.command:
cat > /tmp/stackalloc_nint.cs << 'EOF'
// Test stackalloc with Span<nint> and Span<nuint>
Span<nint> signed = stackalloc nint[5];
for (int i = 0; i < signed.Length; i++)
    signed[i] = i * 10;

Span<nuint> unsigned = stackalloc nuint[3];
for (int i = 0; i < unsigned.Length; i++)
    unsigned[i] = (nuint)(i + 100);

Console.WriteLine($"Span<nint> length: {signed.Length}, values: {signed[0]}, {signed[1]}, {signed[2]}, {signed[3]}, {signed[4]}");
Console.WriteLine($"Span<nuint> length: {unsigned.Length}, values: {unsigned[0]}, {unsigned[1]}, {unsigned[2]}");
Console.WriteLine($"nint size: {sizeof(nint)} bytes");
EOF
